export const features=[{"id":"trail","level":600,"title":"A treasure trail","text":"Each new campaign win earns a roll. Move around the trail for coins, packs and helpers. Replaying old levels does not earn rolls.","action":"ev:trail","target":".treasure-trail","icon":"dice"},{"id":"memory","level":2500,"title":"Pip’s matching garden","text":"Every two new campaign wins earn a seed. A seed lets you turn over two tiles. Match pairs for coins; finish the garden for a pack and Joker.","action":"ev:memory","target":".memory-board","icon":"pairs"},{"id":"welcome","level":1,"title":"A little adventure together","text":"I’m Pip! Follow the glowing stop on the road. Pick it, then press Play. I’ll introduce new places as you reach them.","action":"previewCurrent","target":".story-node.current","icon":"play"},{"id":"garden","level":3,"title":"Grow your helper coins","text":"Gem Garden turns matches into coins. Those coins buy one-use helpers for your cards. You can always return to your saved hand.","action":"gems","target":"[data-action=\"gems\"]","icon":"gems"},{"id":"missions","level":5,"title":"Your daily picnic","text":"Playing cards, winning hands and opening packs fill these tasks naturally. Collect a finished task to reveal another — up to six in 24 hours.","action":"ev:missions","target":"[data-action=\"ev:missions\"]","icon":"missions"},{"id":"wheel","level":7,"title":"A spin along the way","text":"There is a daily spin, plus earned spins every five wins. The wheel gives coins and helpers for your next hand.","action":"wheel","target":"[data-action=\"wheel\"]","icon":"wheel"},{"id":"album","level":15,"title":"A parcel of memories","text":"Find a pack on a card and win the hand to keep it. Open packs in your album, collect sets, and trade duplicate tokens for more packs.","action":"ev:album","target":"[data-action=\"ev:pack\"]","icon":"album"},{"id":"tournament","level":25,"title":"Trophies won’t wait!","text":"Trophy badges disappear after five actions while exposed. Collect those cards promptly, win to bank the trophies, then collect tournament milestones.","action":"ev:tournament","target":"[data-action=\"ev:tournament\"]","icon":"trophy"},{"id":"balloon","level":35,"title":"Take the balloon trail","text":"Start a flight, then win three new campaign levels. Arrow cards on those hands provide darts for the Souvenir Hunt.","action":"ev:balloon","target":"[data-action=\"ev:balloonStart\"]","icon":"balloon"},{"id":"hunt","level":35,"title":"Your arrows reveal treasures","text":"Each arrow uncovers one island tile. Coins, helpers and packs wait underneath. Every ten shots also earns a small arrow refill.","action":"ev:hunt","target":".hunt-board","icon":"arrow"},{"id":"bingo","level":45,"title":"A ticket from your wins","text":"Wins earn bingo draws. Draw numbers to complete rows, columns and diagonals for coins and sticker packs.","action":"ev:bingo","target":"[data-action=\"ev:bingoDraw\"]","icon":"bingo"},{"id":"regatta","level":60,"title":"Let’s sail together","text":"Consecutive new campaign wins move your boat farther. The other crews are computer-controlled. Collect rewards at your own distance milestones.","action":"ev:regatta","target":".regatta-sea","icon":"helm"},{"id":"voyage","level":80,"title":"A monthly voyage","text":"Your campaign wins also move this monthly reward track. Collect each reached port for coins, packs and consumable helpers.","action":"ev:voyage","target":".reward-track","icon":"anchor"},{"id":"travel","level":101,"title":"A whole world of places","text":"Travel Hub lists every chapter with its own picture. Return to earlier stops for missing stars, postcards and a better chapter chest.","action":"ev:travel","target":".travel-list","icon":"travel"},{"id":"chest","level":4,"title":"Stars improve your treasure","text":"The chapter chest can be opened once. More chapter stars improve its prize, so you can collect it now or return after earning more stars.","action":"ev:chest","target":"[data-action^=\"ev:chest-\"]","icon":"chest"},{"id":"postcard","level":3,"title":"A memory of this place","text":"Six chapter stars unlock its postcard. Your postcard and Travel Hub use the same chapter scenery you explore on the road.","action":"ev:postcard","target":".postcard-art","icon":"postcard"},{"id":"tickets","level":90,"title":"A longer little trail","text":"This weekly trail asks for ten consecutive new campaign wins. Finish it for coins, TNT and a four-star sticker pack.","action":"ev:tickets","target":"[data-action=\"ev:ticketStart\"]","icon":"ticket"},{"id":"milestones","level":10,"title":"Every little step counts","text":"Your lifetime clears, wins, stars and other actions build long-term rewards. Collect each reached milestone to begin the next tier.","action":"ev:milestones","target":".event-row","icon":"medal"},{"id":"customize","level":101,"title":"A chapter, a new card back","text":"Finishing all 100 levels in a chapter unlocks its card back and table. Choose an earned design in your card studio. These change the look, never the rules.","action":"ev:customize","target":".customization-grid","icon":"studio"}];
export const mechanicLessons={"1":["Ice needs two matches","Match once to thaw this card, then match again to collect it. Temporary Thaw bypasses the first hit."],"2":["A key for the locks","Collect key cards to open locks further up the field. Helpers that remove a key still collect its effect."],"3":["A locked little door","Find the shown number of keys first, or use a temporary Keypass."],"4":["Mind the fuse","Bomb numbers count successful actions, not seconds. Collect them before zero, or pause fuses with Shield."],"5":["A gift in your cards","Collect this gift card for extra stock. Win the hand to keep any sticker pack badges you collect."],"6":["The numbers are climbing","Arrow cards change rank after each action. Watch their current number before choosing a match."],"7":["The numbers are falling","Down-arrow cards lose one rank after each action. Ace and King wrap around."],"8":["Chip away the armor","Match the card several times to break its stone armor before collecting it."],"9":["Untangle the vines","Build the shown streak without drawing, or use temporary Prune."],"10":["A lantern lights the way","Collect it for a brief glow showing available matches."],"11":["A little lucky harvest","Collect it, then keep matching while its timer runs to grow extra stock."],"12":["A moment of shelter","Collect a shield card to pause bomb fuses briefly."],"13":["Sun and moon gates","The phase changes after actions. Wait for the matching phase or use temporary Phase."],"14":["A seal of color","Match the waste color to the seal, or use a Wild to bypass it."],"15":["A whirl of new numbers","Clearing a tornado replaces the ranks and suits of exposed cards. Look over the field again afterward."],"16":["A glimpse through the fog","The face appears for one action window, then hides again. Take another action to change its window."]};
export const briefGuides={"trail":"New wins → rolls → treasure.","memory":"New wins → seeds → matching pairs.","welcome":"I’m Pip! Pick the glowing stop, then Play.","cards":"Match one higher or lower. Stuck? Draw a card.","garden":"Match gems → coins → helpers.","missions":"Play. Fill a task. Collect your picnic reward.","wheel":"Spin for coins and helpers.","album":"Open packs. Complete sets.","tournament":"Collect trophies, then win the hand.","balloon":"Fly through 3 wins → earn arrows.","hunt":"Use arrows to uncover treasure.","bingo":"Wins → draws → bingo rewards.","regatta":"New wins move your boat.","voyage":"Wins unlock the next port.","travel":"Pick a chapter to revisit.","chest":"More stars → a better chest.","postcard":"6 stars → a postcard.","tickets":"10 new wins → a trail prize.","milestones":"Collect rewards for your progress.","customize":"Finish a chapter → a new back and table.","help":"Pick a picture. I’ll show you the way."};
export const explanations={"pack":["Opening sticker packs","A pack contains a small group of stickers, including at least one matching its rarity. New stickers join your album; duplicates become tokens. Rewards are saved before the reveal animation.","Open packs → complete sets → exchange duplicate tokens for more packs.","pack"],"tokenShop":["Duplicate token shop","Duplicate stickers become tokens. Choose an affordable pack rarity to trade your tokens. The pack goes to your album, ready to open.","Duplicate stickers → tokens → a new pack → another chance to finish a set.","token"],"albums":["Completed album gallery","A finished album remains in your gallery when you start the next one. Browse earlier collections here; rewards can only be collected once.","Finish a collection → keep it here → begin another album.","album"],"shop":["A helping hand","Spend coins on single-use helpers. Buying adds one to your basket; use it from the card table. Only discovered helpers appear.","Match gems for coins → buy a helper → return to the same hand.","extra"],"wheel":["A little luck","Use an earned spin, or the daily spin when its timer is ready. Every five solitaire wins earns another spin. Each of the eight prizes is equally likely.","Spin → receive coins or a helper → bring it to your next hand.","wheel"],"gems":["Gem Garden","Select a gem and an adjacent gem to swap. A valid swap connects at least three. Matches and cascades immediately earn coins. Fresh Garden refills the board and moves once per hour.","Match gems → earn coins → visit the helper shop → return to your cards.","gems"],"settings":["Your adventure settings","Sound and reduced motion apply throughout the game. Export makes a backup file. Import replaces this device’s save with the selected backup. Windows and browser saves are independent.","Export on one device → import on the other to move your progress.","settings"],"cards":["Your card table","Take an uncovered card one rank above or below the current face-up card. Ace connects to King and Two. Draw from the stock whenever you need another rank.","Clear cards → build a streak → win stars, coins and activity rewards.","cardProgress"],"hub":["Your little adventures","These places connect to your solitaire journey. Wins advance several activities at once. Colored badges show something to collect or use. Locked places show the level where Pip introduces them.","Play cards → collect rewards → spend them in the connected activity.","compass"],"journal":["Your meadow journal","Your journal brings together progress, picnic tasks and saved levels. Collect completed tasks for coins. Save a level at the card table to revisit it here.","Play a saved level to improve stars, or return to your current hand.","journal"],"guide":["Pip’s field guide","Special card badges describe their obstacles. Helpers are temporary consumables. Use the information buttons beside helpers and activities whenever you want a reminder.","Try a mechanic on the table, then ask Pip if you need a hand.","ruleBook"],"default":["Your next little step","Use the navigation above to move between your cards, map, activities and helper shop. Your unfinished hand stays saved as you explore.","You can return to the same cards whenever you are ready.","compass"]};
